#define EIGEN_NON_ARDUINO
#include <iomanip>
#include <iostream>
#include "util/W3dSimCommon.h"
int main(int argc, char** argv) {
    if (argc != 2) return 2;
    const auto seeds = w3d_random_seeds_from_env();
    auto noise = make_imu_noise_model(1.51e-3f*g_std, 8e-3f*g_std, 0.0005f,
                                     seeds.accel_noise, seeds.accel_initialization);
    WaveDataCSVReader reader(argv[1]);
    int count = 0;
    std::cout << std::setprecision(std::numeric_limits<float>::max_digits10);
    reader.for_each_record([&](const Wave_Data_Sample& row) {
        if (count++ >= 60000) return;
        const Vector3f measured = apply_imu_noise(Vector3f(row.imu.acc_bx,row.imu.acc_by,row.imu.acc_bz),noise,.005f);
        std::cout << measured.norm() << '\n';
    });
    return count >= 60000 ? 0 : 1;
}
